package ru.pulsedoma.issues;
import org.springframework.stereotype.Service;
import java.math.*;
import java.util.*;
@Service
public class PaymentComparisonService {
 private final HouseTariffService tariffs;
 public PaymentComparisonService(HouseTariffService tariffs){this.tariffs=tariffs;}
 public record Line(String seriesId,HouseTariffService.Rate previous,HouseTariffService.Rate current,boolean comparable,BigDecimal perUnitDifference,BigDecimal percent,BigDecimal quantity,BigDecimal previousEstimate,BigDecimal estimate,String explanation){}
 public record Comparison(String from,String to,List<Line> lines,String limitation){}
 public Comparison compare(String house,OperationsRequests.Comparison r,String user){if(r.to().isBefore(r.from())||r.from().plusYears(10).isBefore(r.to()))throw CaseExchangeService.invalid("Выберите даты в правильном порядке с интервалом до 10 лет");if(r.quantity()!=null&&(r.seriesId()==null||r.seriesId().isBlank()))throw CaseExchangeService.invalid("Для оценки выберите одну услугу");var before=tariffs.catalogue(house,r.from(),user).rates();var after=tariffs.catalogue(house,r.to(),user).rates();Set<String> series=new LinkedHashSet<>();before.forEach(t->series.add(t.seriesId()));after.forEach(t->series.add(t.seriesId()));var lines=new ArrayList<Line>();for(String key:series){if(r.seriesId()!=null&&!r.seriesId().isBlank()&&!key.equals(r.seriesId()))continue;var a=before.stream().filter(t->t.seriesId().equals(key)).findFirst().orElse(null);var b=after.stream().filter(t->t.seriesId().equals(key)).findFirst().orElse(null);boolean comparable=a!=null&&b!=null&&a.unit()==b.unit()&&a.unitLabel().equals(b.unitLabel())&&a.provider().equals(b.provider())&&a.applicability().equals(b.applicability());BigDecimal diff=comparable?b.amount().subtract(a.amount()):null,percent=comparable&&a.amount().signum()!=0?diff.multiply(new BigDecimal("100")).divide(a.amount(),2,RoundingMode.HALF_UP):null;BigDecimal qty=comparable?r.quantity():null;lines.add(new Line(key,a,b,comparable,diff,percent,qty,qty==null?null:a.amount().multiply(qty).setScale(2,RoundingMode.HALF_UP),qty==null?null:b.amount().multiply(qty).setScale(2,RoundingMode.HALF_UP),!comparable?"Для одной из дат нет сопоставимой проверенной ставки или изменились единицы, поставщик либо условия. Автоматического вывода об изменении платежа нет.":diff.signum()==0?"Ставка не изменилась. Сумма квитанции может зависеть от объёма и других условий.":"Изменилась ставка за единицу. Основание и пояснение указаны в публикации; изменение всей квитанции здесь не определяется."));}if(r.seriesId()!=null&&!r.seriesId().isBlank()&&lines.isEmpty())throw CaseExchangeService.invalid("На выбранные даты нет этой опубликованной услуги");return new Comparison(r.from().toString(),r.to().toString(),lines,"Оценка при одинаковом объёме: только объём × ставка. Без льгот, перерасчётов, задолженности, общедомовых начислений и сложных формул. Это не расчёт квитанции и не заключение о законности начисления.");}
}
